import React, { useEffect, useState } from "react";
import { supabase } from "../supabaseClient";
import SlotCard from "../components/SlotCard";

const UserDashboard = () => {
  const [slots, setSlots] = useState([]);
  const [loading, setLoading] = useState(true);

  // Fetch slot status in real-time
  useEffect(() => {
    fetchSlots();
    const interval = setInterval(fetchSlots, 2000); // Poll every 2 seconds
    return () => clearInterval(interval);
  }, []);

  async function fetchSlots() {
    // We are fetching the physical slots, not the logs
    const { data, error } = await supabase
      .from("parking_slots")
      .select("*")
      .order("slot", { ascending: true });

    if (error) console.log("Error:", error);
    else setSlots(data || []);
    setLoading(false);
  }

  // Calculate stats
  const totalSlots = slots.length;
  const occupiedCount = slots.filter((s) => s.status === "occupied").length;
  const availableCount = totalSlots - occupiedCount;

  return (
    <main className="dashboard-root">
      
      {/* 1. MAIN STATS (Available vs Occupied) */}
      <section className="stats-container">
        
        {/* Available Card */}
        <div className="stat-card green">
          <div className="stat-title">Available Slots</div>
          <div className="stat-value">{availableCount}</div>
          <div className="stat-sub">out of {totalSlots} total slots</div>
        </div>

        {/* Occupied Card */}
        <div className="stat-card red">
          <div className="stat-title">Occupied Slots</div>
          <div className="stat-value">{occupiedCount}</div>
          <div className="stat-sub">currently parked</div>
        </div>

      </section>

      {/* 2. PARKING LAYOUT GRID */}
      <section className="layout-section">
        <div className="layout-header">Parking Layout - Real-time Status</div>
        
        <div className="slots-grid">
          {loading ? (
            <p style={{color:'white'}}>Loading system...</p>
          ) : (
            slots.map((slot) => (
              <SlotCard key={slot.id} slot={slot} />
            ))
          )}
        </div>
      </section>

    </main>
  );
};

export default UserDashboard;
